#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <string>
#include <filesystem>
#include <cstring>
#include <cstdio>
#include <cstdlib>
#include <unistd.h>
#include "source_kernels.inc"
#include "study_params.h"
#define C(expr) do{auto e=(expr);if(e!=cudaSuccess){fprintf(stderr,"CUDAfailure:%s line%d\n",cudaGetErrorString(e),__LINE__);exit(1);}}while(0)
struct Buffer {unsigned char *base,*ptr;std::vector<unsigned char> initial;Buffer(std::vector<unsigned char> x){initial.assign(16,211);initial.insert(initial.end(),x.begin(),x.end());initial.insert(initial.end(),16,211);C(cudaMalloc(&base,initial.size()));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size(),cudaMemcpyHostToDevice));}void capture(std::vector<int>&a){std::vector<unsigned char> v(initial.size());C(cudaMemcpy(v.data(),base,v.size(),cudaMemcpyDeviceToHost));for(auto q:v)a.push_back(q);}~Buffer(){cudaFree(base);}};
std::vector<unsigned char> read_image(const CaseSpec&s){std::ifstream f(s.input,std::ios::binary);std::vector<unsigned char>a(s.n);f.read((char*)a.data(),s.n);if(f.gcount()!=s.n){fprintf(stderr,"Inputextent %s\n",s.input);exit(1);}return a;}
struct Work{CaseSpec s;Buffer data,intermediate,theta;Work(const CaseSpec&spec):s(spec),data(read_image(spec)),intermediate(std::vector<unsigned char>(spec.n,0)),theta(std::vector<unsigned char>(spec.n,0)){}void reset(){data.reset();intermediate.reset();theta.reset();}void capture(std::vector<int>&a){data.capture(a);intermediate.capture(a);theta.capture(a);}void launch(int k){dim3 th(TILE,TILE),gr((s.cols-2)/TILE,(s.rows-2)/TILE);if(k==1)gaussian_kernel<<<gr,th,SHMEM>>>(data.ptr,intermediate.ptr,s.rows,s.cols);if(k==2)sobel_kernel<<<gr,th,SHMEM>>>(intermediate.ptr,data.ptr,theta.ptr,s.rows,s.cols);if(k==3)non_max_supp_kernel<<<gr,th,SHMEM>>>(data.ptr,intermediate.ptr,theta.ptr,s.rows,s.cols);if(k==4)hyst_kernel<<<gr,th,0>>>(intermediate.ptr,data.ptr,s.rows,s.cols);C(cudaGetLastError());}};
void coefficients(std::vector<int>&out){float gauss[9];int x[9],y[9];C(cudaMemcpyFromSymbol(gauss,c_gaus,36));C(cudaMemcpyFromSymbol(x,c_sobx,36));C(cudaMemcpyFromSymbol(y,c_soby,36));for(float v:gauss){int bits;memcpy(&bits,&v,4);out.push_back(bits);}out.insert(out.end(),x,x+9);out.insert(out.end(),y,y+9);}
std::vector<int> read_oracle(const char*name,int count){std::ifstream f(name,std::ios::binary);std::vector<int>a(count);f.read((char*)a.data(),count*4);if(f.gcount()!=count*4){fprintf(stderr,"Oracleextent %s\n",name);exit(1);}return a;}
bool check(const std::vector<int>&a,const std::vector<int>&expected,bool trace,int&maximum){if(a.size()!=expected.size())return false;bool ok=true;maximum=0;if(!trace){for(int i=0;i<PREFIX;i++){int d=abs(a[i]-expected[i]);maximum=std::max(maximum,d);ok=ok&&d==0;}int off=PREFIX;for(auto&s:SPECS)for(int k=0;k<3;k++){for(int j=0;j<s.n+32;j++){int d=abs(a[off+j]-expected[off+j]);maximum=std::max(maximum,d);int budget=k==1&&j>=16&&j<s.n+16?1:0;ok=ok&&d<=budget;}off+=s.n+32;}}else{int off=0;for(auto&s:SPECS)for(int k=0;k<5;k++){for(int j=0;j<s.n+32;j++){int d=abs(a[off+j]-expected[off+j]);maximum=std::max(maximum,d);int budget=(k==1||k==3)&&j>=16&&j<s.n+16?1:0;ok=ok&&d<=budget;}off+=s.n+32;}}return ok;}
void dump(const std::string&p,const std::vector<int>&a){std::ofstream f(p,std::ios::binary);f.write((const char*)a.data(),a.size()*4);if(!f)exit(2);}
int main(int argc,char**argv){auto expected=read_oracle(argv[1],COUNT),trace_expected=read_oracle(argv[2],TRACE_COUNT);std::filesystem::create_directories(argv[3]);std::string trace_path=std::string(argv[3])+"/untimed_trace_"+std::to_string(getpid())+".bin";std::vector<Work*>works;for(auto&s:SPECS)works.push_back(new Work(s));

 const void* functions[4]={(const void*)gaussian_kernel,(const void*)sobel_kernel,(const void*)non_max_supp_kernel,(const void*)hyst_kernel};
 for(int k=0;k<4;k++){cudaFuncAttributes attr;C(cudaFuncGetAttributes(&attr,functions[k]));printf("STUDY_NATIVE_RESOURCE stage=%d registers=%d static_shared_bytes=%zu local_bytes=%zu max_dynamic_shared_bytes=%d selected_launch_dynamic_bytes=%d original_driver_dynamic_bytes=%d binary_arch=%d ptx_arch=%d\n",k+1,attr.numRegs,attr.sharedSizeBytes,attr.localSizeBytes,attr.maxDynamicSharedSizeBytes,k<3?SHMEM:0,SHMEM,attr.binaryVersion,attr.ptxVersion);}
 auto pipeline=[&](){for(auto w:works)for(int k=1;k<=4;k++)w->launch(k);C(cudaDeviceSynchronize());};pipeline();
 for(int trial=1;trial<=5;trial++){for(auto w:works)w->reset();std::vector<int> actual;coefficients(actual);for(auto w:works){auto&s=w->s;actual.insert(actual.end(),{s.caseid,s.frame,s.rows,s.cols,TILE});w->capture(actual);}C(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();pipeline();C(cudaDeviceSynchronize());double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();coefficients(actual);if(actual.size()!=PREFIX)return 3;for(auto w:works)w->capture(actual);int err=0;bool ok=check(actual,expected,false,err);std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/ced_trial"+std::to_string(trial)+".bin";dump(path,actual);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"resident12frames_48source_kernel_launches_whole_device_completion\",\"internal_repeats\":1,\"iterations\":1,\"frames\":12,\"kernel_launches\":48,\"supplemental_trace_path\":\"%s\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",actual.size(),err,trace_path.c_str(),path.c_str(),actual.size());fflush(stdout);if(!ok)return 4;}
 // Actual stage trace, AFTER all primary timings; no extra five-trial series.
 std::vector<int> trace;for(auto w:works){w->reset();w->launch(1);w->intermediate.capture(trace);w->launch(2);w->data.capture(trace);w->theta.capture(trace);w->launch(3);w->intermediate.capture(trace);w->launch(4);w->data.capture(trace);}int error=0;bool traceok=check(trace,trace_expected,true,error);dump(trace_path,trace);printf("STUDY_AUXILIARY untimed_complete_stage_trace correct=%s checked_values=%zu max_abs_error=%d path=%s\n",traceok?"true":"false",trace.size(),error,trace_path.c_str());for(auto w:works)delete w;return traceok?0:5;}
